def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]==2: sr,sc=r,c
    d=(1,0) if sr==0 else (0,1) if sc==0 else (-1,0) if sr==h-1 else (0,-1)
    seen={(sr,sc)}
    def inb(r,c): return 0<=r<h and 0<=c<w
    def wall(r,c): return not inb(r,c) or g[r][c]==8   # edge and 8 both block
    stack=[(sr,sc,d)]
    while stack:
        r,c,v=stack.pop()
        if (r,c) not in seen:
            seen.add((r,c)); out[r][c]=2
        nr,nc=r+d[0],c+d[1]
        if inb(nr,nc) and g[nr][nc]!=8 and (nr,nc) not in seen:
            stack.append((nr,nc,d)); continue
        # blocked in flow direction
        if not inb(nr,nc):
            continue  # reached grid edge in flow dir: stop this branch
        # wall: branch perpendicular both ways
        for p in ((d[1],d[0]),(-d[1],-d[0])):
            pr,pc=r+p[0],c+p[1]
            if inb(pr,pc) and g[pr][pc]!=8 and (pr,pc) not in seen:
                stack.append((pr,pc,p))
    return out

